-- Logo upload: managers and administrators may write their own company's files in company-assets (logos/<company id>.*).
create policy company_assets_read on storage.objects for select to authenticated using (bucket_id = 'company-assets' and split_part(name,'/',2) like (public.auth_company_id()::text || '%'));
create policy company_assets_insert on storage.objects for insert to authenticated with check (bucket_id = 'company-assets' and split_part(name,'/',2) like (public.auth_company_id()::text || '%') and (public.is_company_admin() or public.auth_is_manager()));
create policy company_assets_update on storage.objects for update to authenticated using (bucket_id = 'company-assets' and split_part(name,'/',2) like (public.auth_company_id()::text || '%') and (public.is_company_admin() or public.auth_is_manager())) with check (bucket_id = 'company-assets' and split_part(name,'/',2) like (public.auth_company_id()::text || '%'));
create policy company_assets_delete on storage.objects for delete to authenticated using (bucket_id = 'company-assets' and split_part(name,'/',2) like (public.auth_company_id()::text || '%') and (public.is_company_admin() or public.auth_is_manager()));
